// frontend-mobile/src/screens/CreateDynamicFormScreen.js
import React, { useState, useEffect } from 'react';
import {
    TextField,
    Button,
    View,
    Text,
    ScrollView,
    StyleSheet,
    TouchableOpacity,
} from 'react-native';
import { SelectList } from 'react-native-dropdown-select-list';
import { Chip } from 'react-native-paper';
import Icon from 'react-native-vector-icons/MaterialIcons';

const validationOptionsData = [
    { key: '', value: 'None' },
    { key: 'required', value: 'Required' },
    { key: 'email', value: 'Valid Email' },
    { key: 'phone', value: 'Valid Phone Number' },
    { key: 'numeric', value: 'Numbers Only' },
    { key: 'alphabetic', value: 'Alphabets Only' },
    { key: 'alphanumeric', value: 'Alphanumeric Only' },
    { key: 'url', value: 'Valid URL' },
    { key: 'password-strong', value: 'Strong Password' },
    { key: 'min-length', value: 'Minimum Length' },
    { key: 'max-length', value: 'Maximum Length' },
    { key: 'match', value: 'Must Match Another Field' },
    { key: 'date-future', value: 'Date Should Be in Future' },
    { key: 'date-past', value: 'Date Should Be in Past' },
    { key: 'no-spaces', value: 'No Spaces Allowed' },
    { key: 'positive-number', value: 'Positive Numbers Only' },
    { key: 'whole-number', value: 'Whole Numbers Only' },
    { key: 'exact-length', value: 'Exact Character Length' },
];

const controlTypesData = [
    { key: 'text', value: 'Text' },
    { key: 'password', value: 'Password' },
    { key: 'email', value: 'Email' },
    { key: 'number', value: 'Number' },
    { key: 'checkbox', value: 'Checkbox' },
    { key: 'radio', value: 'Radio' },
    { key: 'select', value: 'Select' },
    { key: 'date', value: 'Date' },
];

const CreateDynamicFormScreen = () => {
    const [rows, setRows] = useState([]);
    const [formName, setFormName] = useState('');
    const [formDescription, setFormDescription] = useState('');

    const addRow = () => {
        setRows([
            ...rows,
            {
                label: '',
                controlType: '',
                placeholder: '',
                errorMessage: '',
                minLength: '',
                maxLength: '',
                options: [],
                validations: [],
            },
        ]);
    };

    const deleteRow = (index) => {
        const updatedRows = rows.filter((_, idx) => idx !== index);
        setRows(updatedRows);
    };

    const updateRow = (index, field, value) => {
        const updatedRows = rows.map((row, idx) => {
            if (idx === index) {
                return { ...row, [field]: value };
            }
            return row;
        });
        setRows(updatedRows);
    };

    const updateValidation = (index, validation) => {
        const updatedRows = rows.map((row, idx) => {
            if (idx === index) {
                const newValidations = row.validations.includes(validation)
                    ? row.validations.filter(v => v !== validation)
                    : [...row.validations, validation];
                return { ...row, validations: newValidations };
            }
            return row;
        });
        setRows(updatedRows);
    };

    const handleSaveForm = async () => {
        if (!formName.trim()) {
            alert('Form Name is required!');
            return;
        }

        const formData = {
            formName: formName,
            formDescription: formDescription,
            fields: rows,
        };

        try {
            const response = await fetch('http://192.168.43.219:5000/api/save-form', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(formData),
            });

            if (response.ok) {
                const result = await response.json();
                alert('Form saved successfully!');
                console.log('Form ID:', result.formId);
                setFormName('');
                setFormDescription('');
                setRows([]);
            } else {
                const error = await response.json();
                console.error('Failed to save form:', error);
                alert('Failed to save form.');
            }
        } catch (error) {
            console.error('Error saving form:', error);
            alert('Error saving form.');
        }
    };

    return (
        <ScrollView style={styles.container}>
            <Text style={styles.title}>Create Dynamic Form</Text>
            <TextField
                style={styles.input}
                label="Form Name *"
                value={formName}
                onChangeText={(text) => setFormName(text)}
            />
            <TextField
                style={styles.input}
                label="Form Description"
                value={formDescription}
                onChangeText={(text) => setFormDescription(text)}
                multiline
                numberOfLines={2}
            />

            <Button title="Add Field" onPress={addRow} />

            {rows.map((row, index) => (
                <View key={index} style={styles.row}>
                    <Text style={styles.rowTitle}>{`Field ${index + 1}`}</Text>
                    <TextField
                        style={styles.input}
                        label="Label"
                        value={row.label}
                        onChangeText={(text) => updateRow(index, 'label', text)}
                    />
                    <SelectList
                        data={controlTypesData}
                        setSelected={(value) => updateRow(index, 'controlType', value)}
                        placeholder="Select Control Type"
                        defaultOption={controlTypesData.find(item => item.key === row.controlType)}
                        style={styles.select}
                    />
                    <TextField
                        style={styles.input}
                        label="Placeholder / Help Text"
                        value={row.placeholder}
                        onChangeText={(text) => updateRow(index, 'placeholder', text)}
                    />
                    <TextField
                        style={styles.input}
                        label="Error Message"
                        value={row.errorMessage}
                        onChangeText={(text) => updateRow(index, 'errorMessage', text)}
                    />
                    {row.controlType === 'text' || row.controlType === 'password' || row.controlType === 'number' ? (
                        <View>
                            <TextField
                                style={styles.input}
                                label="Min Length"
                                value={row.minLength}
                                keyboardType="numeric"
                                onChangeText={(text) => updateRow(index, 'minLength', text)}
                            />
                            <TextField
                                style={styles.input}
                                label="Max Length"
                                value={row.maxLength}
                                keyboardType="numeric"
                                onChangeText={(text) => updateRow(index, 'maxLength', text)}
                            />
                        </View>
                    ) : null}

                    <View style={styles.validationsContainer}>
                        <Text style={styles.validationLabel}>Validations:</Text>
                        <View style={styles.chipsContainer}>
                            {validationOptionsData.map(option => (
                                <Chip
                                    key={option.key}
                                    onPress={() => updateValidation(index, option.key)}
                                    style={[
                                        styles.chip,
                                        row.validations.includes(option.key) && styles.chipSelected,
                                    ]}
                                    textStyle={row.validations.includes(option.key) && styles.chipTextSelected}
                                >
                                    {option.value}
                                </Chip>
                            ))}
                        </View>
                    </View>

                    <TouchableOpacity onPress={() => deleteRow(index)} style={styles.deleteButton}>
                        <Icon name="delete" size={24} color="red" />
                    </TouchableOpacity>
                </View>
            ))}

            <Button title="Save Form" onPress={handleSaveForm} />
        </ScrollView>
    );
};

const styles = StyleSheet.create({
    container: {
        flex: 1,
        padding: 20,
    },
    title: {
        fontSize: 24,
        fontWeight: 'bold',
        marginBottom: 20,
    },
    input: {
        marginBottom: 15,
    },
    row: {
        marginBottom: 20,
        padding: 15,
        borderColor: '#ccc',
        borderWidth: 1,
        borderRadius: 5,
    },
    rowTitle: {
        fontSize: 18,
        fontWeight: 'bold',
        marginBottom: 10,
    },
    deleteButton: {
        position: 'absolute',
        top: 10,
        right: 10,
    },
    select: {
        marginBottom: 15,
    },
    validationsContainer: {
        marginBottom: 15,
    },
    validationLabel: {
        fontWeight: 'bold',
        marginBottom: 5,
    },
    chipsContainer: {
        flexDirection: 'row',
        flexWrap: 'wrap',
        gap: 5,
    },
    chip: {
        backgroundColor: '#e0e0e0',
    },
    chipSelected: {
        backgroundColor: '#2196f3',
    },
    chipTextSelected: {
        color: 'white',
    },
});

export default CreateDynamicFormScreen;
